import sys
from collections import deque

def is_tree(f, l, r, n, m):
    positions = [None] * (r - l + 1)
    for i in range(n):
        for j in range(m):
            if l <= f[i][j] <= r:
                positions[f[i][j] - l] = (i, j)

    if len(positions) != r - l + 1:
        return False

    visited = [[False] * m for _ in range(n)]
    queue = deque([positions[0]])
    visited[positions[0][0]][positions[0][1]] = True
    count = 0

    while queue:
        x, y = queue.popleft()
        count += 1
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and l <= f[nx][ny] <= r and not visited[nx][ny]:
                visited[nx][ny] = True
                queue.append((nx, ny))

    return count == r - l + 1

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    m = int(input[1])
    f = []
    index = 2
    for i in range(n):
        f.append(list(map(int, input[index:index + m])))
        index += m

    total = 0
    for l in range(1, n * m + 1):
        for r in range(l, n * m + 1):
            if is_tree(f, l, r, n, m):
                total += 1

    print(total)

if __name__ == "__main__":
    main()
